export const PROTOCOL_VERSION = 1 as const;

export type MissionState =
  | 'READY' | 'RUNNING' | 'VERIFYING' | 'PAUSED' | 'BLOCKED'
  | 'NEEDS_RECONCILIATION' | 'COMPLETED' | 'CANCELLED';
export type Sandbox = 'read-only' | 'workspace-write';
export type MissionMode = 'supervised' | 'autopilot';

/** Trusted operator-supplied executable arguments; never generated by the model. */
export interface VerificationCheck {
  argv: string[];
  timeoutMs: number;
}

export interface CreateMission {
  goal: string;
  acceptance: string[];
  workspace: string;
  sandbox: Sandbox;
  mode: MissionMode;
  maxTurns: number;
  requestKey: string;
  checks?: VerificationCheck[];
}

export interface Mission extends CreateMission {
  id: string;
  checks: VerificationCheck[];
  state: MissionState;
  version: number;
  turnCount: number;
  threadId: string | null;
  nextInstruction: string | null;
  lastSummary: string | null;
  lastError: string | null;
  ownerPid: number | null;
  ownerHost: string | null;
  stopRequested: boolean;
  createdAt: string;
  updatedAt: string;
}

export type Decision = {
  status: 'continue' | 'candidate_complete' | 'blocked';
  summary: string;
  next_instruction: string;
  evidence: string[];
};

export type Verification = {
  accepted: boolean;
  reason: string;
  evidence: string[];
};

export interface MissionEvent {
  id: number;
  missionId: string;
  createdAt: string;
  type: string;
  payload: unknown;
}

export interface TurnInput {
  mission: Mission;
  prompt: string;
  onThreadStarted: (id: string) => void;
  onEvent?: (type: string) => void;
}

/** Agent runtimes are replaceable; mission state is not owned by an agent. */
export interface AgentAdapter {
  execute(input: TurnInput): Promise<Decision>;
  verify(mission: Mission, decision: Decision): Promise<Verification>;
}
